//! Brand constants, magic headers, and domain markers for Mesh VPN.

/// Human-readable product name.
pub const PRODUCT_NAME: &str = "Mesh VPN";

/// CLI binary name.
pub const CLI_BINARY_NAME: &str = "mesh";

/// Privileged local daemon binary name.
pub const DAEMON_BINARY_NAME: &str = "meshd";

/// Control + Relay + STUN server binary name.
pub const SERVER_BINARY_NAME: &str = "mesh-server";

/// Default DNS suffix appended to peer hostnames inside `/etc/hosts`.
pub const DEFAULT_DOMAIN_SUFFIX: &str = "mesh.internal";

/// Prefix for pre-authentication tokens generated by the control server.
pub const PREAUTH_KEY_PREFIX: &str = "mpk_";

/// Outer magic header for Disco traversal packets (`"MESHDS"`).
pub const DISCO_MAGIC: [u8; 6] = *b"MESHDS";

/// Inner plaintext context domain-separation tag for Disco NaCl boxes.
pub const DISCO_INNER_CTX: [u8; 8] = *b"MESHDSv1";

/// Inner context magic header for offline emergency revocation blobs.
pub const EMERGENCY_REVOKE_MAGIC: [u8; 8] = *b"MESHERV1";

/// TLS RFC 5705 exporter label used to bind challenge proofs to the active TLS session.
pub const TLS_EXPORTER_LABEL: &[u8] = b"EXPORTER-mesh-control-v1";

/// Start delimiter for the daemon-managed block in the system hosts file.
pub const HOSTS_BEGIN_MARKER: &str = "# BEGIN mesh managed hosts (do not edit manually)";

/// End delimiter for the daemon-managed block in the system hosts file.
pub const HOSTS_END_MARKER: &str = "# END mesh managed hosts";

/// Hostname labels reserved from node registration and hosts-file mapping.
pub const RESERVED_HOSTNAMES: [&str; 5] = ["localhost", "broadcasthost", "wpad", "isatap", "local"];
